/** Actual HOST filesystem/JCA/CAS methods with PRIVATE synthetic source/key/path; NOT Android. */
public class BrowserMetadataStoreTest {
 static class F implements AutoCloseable {
  final Path root=Files.createTempDirectory("browser-metadata-host-");final AtomicReference<ComponentGate.SourceView> source=new AtomicReference<>(ComponentGate.SourceView.acceptedNative(new Object(),new byte[16]));final ComponentGate gate=ComponentGate.forNativeSource(ProcessRole.MAIN,source::get);final ComponentGate.BusinessPermit permit=gate.requireBusiness();final PrivateRecordStore records;final OwnedDataCatalog catalog;final BookmarkStore bookmarks;final HistoryStore history;final SettingsRepository settings;final SubapplicationCoordinator apps;
  F()throws Exception{Constructor<DataKeyVault> v=DataKeyVault.class.getDeclaredConstructor(SecretKey.class,ComponentGate.class,byte[].class,boolean.class);v.setAccessible(true);DataKeyVault vault=v.newInstance(new SecretKeySpec(new byte[32],"AES"),gate,new byte[16],false);Constructor<PrivateRecordStore> c=PrivateRecordStore.class.getDeclaredConstructor(Path[].class,ComponentGate.class,byte[].class,DataKeyVault.class,boolean.class);c.setAccessible(true);records=c.newInstance(new Path[]{root},gate,new byte[16],vault,false);catalog=OwnedDataCatalog.openExisting(records,gate,permit);bookmarks=new BookmarkStore(catalog);history=new HistoryStore(catalog,permit);settings=new SettingsRepository(catalog);apps=new SubapplicationCoordinator(settings);}
  PrivateRecordStore.Reference ref(OwnedDataCatalog.Family f){return records.reference(f.purpose,f.scope,permit);}
  void seedSettings(boolean music)throws Exception{try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=settings.read(permit)){settings.compareAndWrite(v,new SettingsRepository.Snapshot(0,SearchEngines.Provider.BING,false,music),permit);}}
  void replaceSettingsRaw(boolean music)throws Exception{try(PrivateRecordStore.ReadRecord r=records.read(ref(OwnedDataCatalog.Family.SETTINGS),permit)){records.write(r.stamp(),SettingsRepository.CODEC.encode(new SettingsRepository.Snapshot(1,SearchEngines.Provider.BING,false,music)),permit);}}
  public void close()throws Exception{try(java.util.stream.Stream<Path> paths=Files.walk(root)){for(Path p:paths.sorted(Comparator.reverseOrder()).toArray(Path[]::new))Files.delete(p);}}
 }
 @Test public void missingIsNotFreshFalseBingOrAutomaticWrite()throws Exception{try(F f=new F();OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit)){assertEquals(PrivateRecordStore.Kind.MISSING,v.kind());assertThrows(IllegalStateException.class,()->v.value(f.permit));assertFalse(Files.exists(f.root.resolve(f.ref(OwnedDataCatalog.Family.SETTINGS).opaqueRef())));}}
 @Test public void allThreeNativeEncryptedFamiliesCoexistAndRoundTrip()throws Exception{try(F f=new F()){try(OwnedDataCatalog.View<BookmarkStore.Snapshot> v=f.bookmarks.read(f.permit)){f.bookmarks.compareAndWrite(v,new BookmarkStore.Snapshot(0,Collections.emptyList()).add("private-title","https://example.test/"),f.permit);}try(OwnedDataCatalog.View<HistoryStore.Snapshot> v=f.history.read(f.permit)){f.history.compareAndWrite(v,new HistoryStore.Snapshot(0,false,Collections.emptyList()).addObservedVisit(new HistoryStore.Page(new HistoryStore.Source("ws_00000000000000000000000000000001","source",BrowserModels.Level.TEMPORARY,true),"tab_00000000000000000000000000000001","history-title","https://example.test/h"),1),f.permit);}f.seedSettings(true);try(OwnedDataCatalog.View<BookmarkStore.Snapshot> v=f.bookmarks.read(f.permit)){assertEquals(1,v.value(f.permit).nodes().size());}try(OwnedDataCatalog.View<HistoryStore.Snapshot> v=f.history.read(f.permit)){assertEquals(1,v.value(f.permit).entries().size());}try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit)){assertTrue(v.value(f.permit).desiredEnabled("music"));}for(OwnedDataCatalog.Family family:OwnedDataCatalog.Family.values()){String bytes=new String(Files.readAllBytes(f.root.resolve(f.ref(family).opaqueRef())),java.nio.charset.StandardCharsets.ISO_8859_1);assertFalse(bytes.contains("private-title"));assertFalse(bytes.contains("history-title"));}}}
 @Test public void retainedDecodedCreditSharedAcrossFamiliesUntilClose()throws Exception{try(F f=new F()){OwnedDataCatalog.View<?> v=f.bookmarks.read(f.permit);assertFalse(f.records.hasOwnedIoInFlight());assertThrows(IllegalStateException.class,()->f.settings.read(f.permit));v.close();try(OwnedDataCatalog.View<?> next=f.history.read(f.permit)){assertEquals(PrivateRecordStore.Kind.MISSING,next.kind());}}}
 @Test public void writeAttemptCannotBeReusedEvenAfterSuccess()throws Exception{try(F f=new F();OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit)){SettingsRepository.Snapshot intended=new SettingsRepository.Snapshot(0,SearchEngines.Provider.BING,false,false);f.settings.compareAndWrite(v,intended,f.permit);assertThrows(IllegalArgumentException.class,()->f.settings.compareAndWrite(v,intended,f.permit));}}
 @Test public void staleReadCannotOverwriteConcurrentNativeWriter()throws Exception{try(F f=new F()){f.seedSettings(false);try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit)){f.replaceSettingsRaw(true);assertThrows(IOException.class,()->f.settings.compareAndWrite(v,v.value(f.permit).withEnabled("music",false),f.permit));}}}
 @Test public void metadataRevisionCannotRegressWhileRecordCasIsCurrent()throws Exception{try(F f=new F()){f.seedSettings(false);try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit)){assertThrows(IllegalArgumentException.class,()->f.settings.compareAndWrite(v,new SettingsRepository.Snapshot(0,SearchEngines.Provider.GOOGLE,true,true),f.permit));}}}
 @Test public void fixedFamilyCannotBeConfusedThroughRawGenericCast()throws Exception{try(F f=new F();OwnedDataCatalog.View<BookmarkStore.Snapshot> v=f.bookmarks.read(f.permit)){@SuppressWarnings({"unchecked","rawtypes"}) OwnedDataCatalog.View<SettingsRepository.Snapshot> raw=(OwnedDataCatalog.View)v;assertThrows(IllegalArgumentException.class,()->f.settings.compareAndWrite(raw,new SettingsRepository.Snapshot(0,SearchEngines.Provider.BING,false,false),f.permit));}}
 @Test public void foreignCatalogViewIsNotLocalWriteAuthority()throws Exception{try(F a=new F();F b=new F();OwnedDataCatalog.View<SettingsRepository.Snapshot> v=a.settings.read(a.permit)){assertThrows(IllegalArgumentException.class,()->b.settings.compareAndWrite(v,new SettingsRepository.Snapshot(0,SearchEngines.Provider.BING,false,false),b.permit));}}
 @Test public void unfinishedStageRetainedAndBlocksReplacement()throws Exception{try(F f=new F()){Path stage=f.root.resolve(f.ref(OwnedDataCatalog.Family.SETTINGS).opaqueRef()+".pending");Files.write(stage,new byte[]{7});try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit)){assertEquals(PrivateRecordStore.Kind.UNFINISHED_WRITE,v.kind());assertThrows(IllegalArgumentException.class,()->f.settings.compareAndWrite(v,new SettingsRepository.Snapshot(0,SearchEngines.Provider.BING,false,false),f.permit));}assertArrayEquals(new byte[]{7},Files.readAllBytes(stage));}}
 @Test public void failedDecoderReleasesCreditsButNeverRepairsCiphertext()throws Exception{try(F f=new F()){PrivateRecordStore.Reference ref=f.ref(OwnedDataCatalog.Family.SETTINGS);try(PrivateRecordStore.ReadRecord read=f.records.read(ref,f.permit)){f.records.write(read.stamp(),new byte[]{1},f.permit);}byte[] old=Files.readAllBytes(f.root.resolve(ref.opaqueRef()));for(int i=0;i<2;i++)assertThrows(IllegalArgumentException.class,()->f.settings.read(f.permit));assertArrayEquals(old,Files.readAllBytes(f.root.resolve(ref.opaqueRef())));assertFalse(f.records.hasOwnedIoInFlight());}}
 @Test public void purposeAndScopeAadRejectMovedEncryptedRecord()throws Exception{try(F f=new F()){f.seedSettings(false);Files.copy(f.root.resolve(f.ref(OwnedDataCatalog.Family.SETTINGS).opaqueRef()),f.root.resolve(f.ref(OwnedDataCatalog.Family.HISTORY).opaqueRef()));assertThrows(GeneralSecurityException.class,()->f.history.read(f.permit));}}
 @Test public void sourceLockAndSameEpochNewIncarnationInvalidateOldOwners()throws Exception{try(F f=new F()){f.seedSettings(false);try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit)){f.source.set(ComponentGate.SourceView.acceptedNative(new Object(),new byte[16]));ComponentGate.BusinessPermit current=f.gate.requireBusiness();assertThrows(SecurityException.class,()->v.value(current));assertThrows(SecurityException.class,()->f.settings.read(current));assertThrows(SecurityException.class,()->OwnedDataCatalog.openExisting(f.records,f.gate,current));}}}
 @Test public void closedViewCannotReadWriteOrAuthorizeHandoff()throws Exception{try(F f=new F()){f.seedSettings(true);OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit);v.close();v.close();assertThrows(IllegalStateException.class,()->f.apps.request(v,"music",SubapplicationCoordinator.Command.OPEN,(d,c,fence)->{},f.permit));assertThrows(IllegalStateException.class,()->v.value(f.permit));}}
 @Test public void desiredDisableDoesNotCallStopOrClaimEnded()throws Exception{try(F f=new F()){f.seedSettings(true);try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.apps.readDesired(f.permit)){assertEquals(2,f.apps.setDesiredEnabled(v,"music",false,f.permit));}try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.apps.readDesired(f.permit)){assertFalse(v.value(f.permit).desiredEnabled("music"));AtomicBoolean called=new AtomicBoolean();assertThrows(SecurityException.class,()->f.apps.request(v,"music",SubapplicationCoordinator.Command.OPEN,(d,c,fence)->called.set(true),f.permit));assertFalse(called.get());}}}
 @Test public void nativeHandoffSpendsBeforeUnknownAndCannotReuseView()throws Exception{try(F f=new F()){f.seedSettings(true);try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.apps.readDesired(f.permit)){assertThrows(IOException.class,()->f.apps.request(v,"music",SubapplicationCoordinator.Command.OPEN,(d,c,fence)->{fence.checkCurrent();throw new IOException();},f.permit));assertThrows(IllegalArgumentException.class,()->f.apps.request(v,"music",SubapplicationCoordinator.Command.OPEN,(d,c,fence)->fail(),f.permit));}}}
 @Test public void handoffFenceRetiresOnReturnAndWrongThread()throws Exception{try(F f=new F()){f.seedSettings(true);try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.apps.readDesired(f.permit)){SubapplicationCoordinator.Fence[] held={null};f.apps.request(v,"music",SubapplicationCoordinator.Command.OPEN,(d,c,fence)->{held[0]=fence;assertEquals("music",d.localId());AtomicBoolean rejected=new AtomicBoolean();Thread t=new Thread(()->{try{fence.checkCurrent();}catch(Exception expected){rejected.set(true);}});t.start();t.join();assertTrue(rejected.get());},f.permit);assertThrows(SecurityException.class,()->held[0].checkCurrent());}}}
 @Test public void stopRequestAllowedForDisabledButNotClaimedActualStop()throws Exception{try(F f=new F()){f.seedSettings(false);try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.apps.readDesired(f.permit)){AtomicInteger count=new AtomicInteger();f.apps.request(v,"music",SubapplicationCoordinator.Command.REQUEST_STOP,(d,c,fence)->{fence.checkCurrent();count.incrementAndGet();},f.permit);assertEquals(1,count.get());assertFalse(v.value(f.permit).desiredEnabled("music"));}}}
 @Test public void settingsChangedDuringHandoffSuppressesLatePositiveReturn()throws Exception{try(F f=new F()){f.seedSettings(true);try(OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.apps.readDesired(f.permit)){assertThrows(IOException.class,()->f.apps.request(v,"music",SubapplicationCoordinator.Command.OPEN,(d,c,fence)->f.replaceSettingsRaw(false),f.permit));}}}
 @Test public void unknownDirectoryObjectsRemainAndStillBlockNewStages()throws Exception{try(F f=new F();OwnedDataCatalog.View<SettingsRepository.Snapshot> v=f.settings.read(f.permit)){Path unknown=f.root.resolve("p7_00000000000000000000000000000000.v1");Files.write(unknown,new byte[]{1});assertThrows(IOException.class,()->f.settings.compareAndWrite(v,new SettingsRepository.Snapshot(0,SearchEngines.Provider.BING,false,false),f.permit));assertArrayEquals(new byte[]{1},Files.readAllBytes(unknown));}}
 @Test public void allFivePurposeCodesAndIndependentCiphertextBindingRemainExact()throws Exception{byte[] key=new byte[32];for(PrivateRecordSealer.Purpose purpose:PrivateRecordSealer.Purpose.values()){PrivateRecordSealer.Binding binding=new PrivateRecordSealer.Binding(purpose,new byte[16],new byte[16],1);byte[] b=PrivateRecordSealer.seal(key,binding,new byte[]{9});assertEquals(purpose.code(),java.nio.ByteBuffer.wrap(b,10,2).getShort());assertArrayEquals(new byte[]{9},PrivateRecordSealer.open(key,binding,b));for(PrivateRecordSealer.Purpose other:PrivateRecordSealer.Purpose.values())if(other!=purpose)assertThrows(GeneralSecurityException.class,()->PrivateRecordSealer.open(key,new PrivateRecordSealer.Binding(other,new byte[16],new byte[16],1),b));}assertEquals(3205,PrivateRecordStore.MAX_RECORDS);}
}
